void readline(int fd, char *line) {
  int count = 0;
  int num_read;

  while (1) {
    num_read = read(fd, line + count, 1);
    if (num_read == 0) {
      break;
    }
    if (line[count] == '\n') {
      line[count] = '\0';
      break;
    }
    count++;
  }
}
int main(int argc, char *argv[]) {
  char **suffix;
  char input_line[100]; // TODO: what should max size be?
  char *command[200];
  int i, j;

  readline(0, input_line);
  suffix = split(input_line);

  // Build up complete command.
  for (i = 1; i < argc; i++) {
    command[i-1] = argv[i];
  }

  for (j = 0;; j++) {
    if (suffix[j] == 0) {
      break;
    }
    command[i - 1 + j] = suffix[j];
  }

  exec("echo", command);
  // printf("%s\n", command[0]);
  // printf("%s\n", command[1]);
  // printf("%s\n", command[2]);
}
